154	
155	public class Database {
156	    private static String dbUrl;
157	    private static String dbUser;
158	    private static String dbPassword;
159	
160	    static {
161	        dbUrl = System.getenv("DB_URL");
162	        dbUser = System.getenv("DB_USER");
163	        dbPassword = System.getenv("DB_PASSWORD");
164	
165	        if (dbUrl == null || dbUser == null || dbPassword == null) {
166	            throw new IllegalStateException("Missing database environment variables");
167	        }
168	    }
169	
170	    public static Connection getConnection() throws SQLException {
171	        return DriverManager.getConnection(dbUrl, dbUser, dbPassword);
172	    }
173	
174	    public static void initialize() {
175	        try (Connection conn = getConnection()) {
176	            createSchema(conn);
177	        } catch (SQLException e) {
178	            throw new RuntimeException(e);
179	        }
180	    }
181	
182	    private static void createSchema(Connection conn) throws SQLException {
183	        String[] statements = {
184	            """
185	            CREATE TABLE IF NOT EXISTS rooms (
186	                number INTEGER PRIMARY KEY,
187	                type VARCHAR(50) NOT NULL,
188	                capacity INTEGER NOT NULL,
189	                nightly_rate NUMERIC(10, 2) NOT NULL
190	            )
191	            """,
192	
193	            """
194	            CREATE TABLE IF NOT EXISTS reservations (
195	                id BIGSERIAL PRIMARY KEY,
196	                room_number INTEGER NOT NULL REFERENCES rooms(number),
197	                guest_name VARCHAR(255) NOT NULL,
198	                guest_email VARCHAR(255) NOT NULL,
199	                guest_cpf VARCHAR(14) NOT NULL,
200	                check_in DATE NOT NULL,
201	                check_out DATE NOT NULL,
202	                guests INTEGER NOT NULL,
203	                rate_plan VARCHAR(50) NOT NULL,
204	                nights INTEGER NOT NULL,
205	                subtotal NUMERIC(10, 2) NOT NULL,
206	                discount NUMERIC(10, 2) NOT NULL,
207	                total NUMERIC(10, 2) NOT NULL,
208	                status VARCHAR(50) NOT NULL,
209	                amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
210	                refund NUMERIC(10, 2)
211	            )
212	            """,
213	
214	            """
215	            CREATE TABLE IF NOT EXISTS messages (
216	                id BIGSERIAL PRIMARY KEY,
217	                channel VARCHAR(50) NOT NULL,
218	                to_address VARCHAR(255) NOT NULL,
219	                subject VARCHAR(255) NOT NULL,
220	                body TEXT NOT NULL
221	            )
222	            """,
223	
224	            """
225	            INSERT INTO rooms (number, type, capacity, nightly_rate)
226	            VALUES
227	                (101, 'STANDARD', 2, 249.90),
228	                (102, 'STANDARD', 2, 249.90),
229	                (201, 'DELUXE', 3, 389.90),
230	                (202, 'DELUXE', 3, 389.90),
231	                (301, 'SUITE', 4, 579.90)
232	            ON CONFLICT (number) DO NOTHING
233	            """
234	        };
235	
236	        for (String sql : statements) {
237	            try (Statement stmt = conn.createStatement()) {
238	                stmt.execute(sql);
239	            }
240	        }
241	    }
242	}

