  1	package com.pousadamarealta;
  2	
  3	import com.pousadamarealta.models.*;
  4	import com.pousadamarealta.exceptions.*;
  5	import com.pousadamarealta.api.*;
  6	import com.pousadamarealta.utils.*;
  7	import com.pousadamarealta.notifications.NotificationManager;
  8	import java.math.BigDecimal;
  9	import java.sql.*;
 10	import java.time.LocalDate;
 11	import java.util.ArrayList;
 12	import java.util.List;
 13	
 14	public class ReservationService {
 15	    public static List<Room> getRooms() {
 16	        List<Room> rooms = new ArrayList<>();
 17	        try (Connection conn = Database.getConnection()) {
 18	            String sql = "SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number";
 19	            try (Statement stmt = conn.createStatement()) {
 20	                try (ResultSet rs = stmt.executeQuery(sql)) {
 21	                    while (rs.next()) {
 22	                        rooms.add(new Room(
 23	                            rs.getInt("number"),
 24	                            RoomType.valueOf(rs.getString("type")),
 25	                            rs.getInt("capacity"),
 26	                            rs.getBigDecimal("nightly_rate")
 27	                        ));
 28	                    }
 29	                }
 30	            }
 31	        } catch (SQLException e) {
 32	            throw new RuntimeException(e);
 33	        }
 34	        return rooms;
 35	    }
 36	
 37	    public static Reservation createReservation(ReservationRequest req) {
 38	        if (req.guestName == null || req.guestName.isEmpty()) {
 39	            throw new IllegalArgumentException("Guest name is required");
 40	        }
 41	        if (req.guestEmail == null || req.guestEmail.isEmpty()) {
 42	            throw new IllegalArgumentException("Guest email is required");
 43	        }
 44	        if (req.guestCpf == null || req.guestCpf.isEmpty()) {
 45	            throw new IllegalArgumentException("Guest CPF is required");
 46	        }
 47	        if (req.checkIn == null) {
 48	            throw new IllegalArgumentException("Check-in date is required");
 49	        }
 50	        if (req.checkOut == null) {
 51	            throw new IllegalArgumentException("Check-out date is required");
 52	        }
 53	        if (req.guests <= 0) {
 54	            throw new IllegalArgumentException("Number of guests must be at least 1");
 55	        }
 56	        if (req.ratePlan == null) {
 57	            throw new IllegalArgumentException("Rate plan is required");
 58	        }
 59	
 60	        LocalDate checkIn = DateParser.parse(req.checkIn);
 61	        LocalDate checkOut = DateParser.parse(req.checkOut);
 62	
 63	        if (!checkOut.isAfter(checkIn)) {
 64	            throw new IllegalArgumentException("Check-out must be after check-in");
 65	        }
 66	
 67	        Room room = findRoom(req.roomNumber);
 68	        if (room == null) {
 69	            throw new NotFoundException("ROOM_NOT_FOUND", "Room not found");
 70	        }
 71	
 72	        if (req.guests > room.capacity) {
 73	            throw new UnprocessableException("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity");
 74	        }
 75	
 76	        checkRoomAvailability(req.roomNumber, checkIn, checkOut, null);
 77	
 78	        RatePlan ratePlan = RatePlan.valueOf(req.ratePlan);
 79	        int nights = PriceCalculator.countNights(checkIn, checkOut);
 80	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(room.nightlyRate, checkIn, checkOut);
 81	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan == RatePlan.NON_REFUNDABLE);
 82	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
 83	
 84	        try (Connection conn = Database.getConnection()) {
 85	            String sql = """
 86	                INSERT INTO reservations
 87	                (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests,
 88	                 rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
 89	                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 90	                RETURNING id
 91	                """;
 92	            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
 93	                stmt.setInt(1, req.roomNumber);
 94	                stmt.setString(2, req.guestName);
 95	                stmt.setString(3, req.guestEmail);
 96	                stmt.setString(4, req.guestCpf);
 97	                stmt.setObject(5, checkIn);
 98	                stmt.setObject(6, checkOut);
 99	                stmt.setInt(7, req.guests);
100	                stmt.setString(8, ratePlan.toString());
101	                stmt.setInt(9, nights);
102	                stmt.setBigDecimal(10, subtotal);
103	                stmt.setBigDecimal(11, discount);
104	                stmt.setBigDecimal(12, total);
105	                stmt.setString(13, ReservationStatus.PENDING.toString());
106	                stmt.setBigDecimal(14, BigDecimal.ZERO);
107	                stmt.setNull(15, Types.NUMERIC);
108	
109	                try (ResultSet rs = stmt.executeQuery()) {
110	                    rs.next();
111	                    long id = rs.getLong("id");
112	                    return getReservation(id);
113	                }
114	            }
115	        } catch (SQLException e) {
116	            throw new RuntimeException(e);
117	        }
118	    }
119	
120	    public static Reservation getReservation(long id) {
121	        try (Connection conn = Database.getConnection()) {
122	            String sql = "SELECT * FROM reservations WHERE id = ?";
123	            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
124	                stmt.setLong(1, id);
125	                try (ResultSet rs = stmt.executeQuery()) {
126	                    if (!rs.next()) {
127	                        throw new NotFoundException("RESERVATION_NOT_FOUND", "Reservation not found");
128	                    }
129	                    return rowToReservation(rs);
130	                }
131	            }
132	        } catch (SQLException e) {
133	            throw new RuntimeException(e);
134	        }
135	    }
136	
137	    public static Reservation confirmReservation(long id) {
138	        Reservation reservation = getReservation(id);
139	
140	        if (reservation.status != ReservationStatus.PENDING) {
141	            throw new ConflictException("OPERATION_NOT_ALLOWED", "Only pending reservations can be confirmed");
142	        }
143	
