 54	import com.pousadamarealta.utils.DateParser;
 55	import com.pousadamarealta.utils.PriceFormatter;
 56	import java.math.BigDecimal;
 57	import java.sql.*;
 58	import java.time.LocalDate;
 59	import java.time.YearMonth;
 60	import java.util.*;
 61	
 62	public class ReportService {
 63	    public static String generateOccupancyReport(String dateStr) {
 64	        LocalDate date = DateParser.parse(dateStr);
 65	
 66	        List<Room> allRooms = ReservationService.getRooms();
 67	        List<Map<String, String>> occupiedRooms = new ArrayList<>();
 68	
 69	        try (Connection conn = Database.getConnection()) {
 70	            String sql = """
 71	                SELECT r.id, r.room_number, room.type, r.check_in, r.check_out
 72	                FROM reservations r
 73	                JOIN rooms room ON r.room_number = room.number
 74	                WHERE r.status != 'CANCELLED'
 75	                AND r.check_in <= ?
 76	                AND r.check_out > ?
 77	                ORDER BY r.room_number, r.id
 78	                """;
 79	            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
 80	                stmt.setObject(1, date);
 81	                stmt.setObject(2, date);
 82	                try (ResultSet rs = stmt.executeQuery()) {
 83	                    while (rs.next()) {
 84	                        Map<String, String> row = new HashMap<>();
 85	                        row.put("room", String.valueOf(rs.getInt("room_number")));
 86	                        row.put("type", rs.getString("type"));
 87	                        row.put("reservation", String.valueOf(rs.getLong("id")));
 88	                        row.put("check_in", DateParser.format(rs.getObject("check_in", LocalDate.class)));
 89	                        row.put("check_out", DateParser.format(rs.getObject("check_out", LocalDate.class)));
 90	                        occupiedRooms.add(row);
 91	                    }
 92	                }
 93	            }
 94	        } catch (SQLException e) {
 95	            throw new RuntimeException(e);
 96	        }
 97	
 98	        StringBuilder csv = new StringBuilder();
 99	        csv.append("room,type,reservation,check_in,check_out\n");
100	        for (Map<String, String> row : occupiedRooms) {
101	            csv.append(row.get("room")).append(",");
102	            csv.append(row.get("type")).append(",");
103	            csv.append(row.get("reservation")).append(",");
104	            csv.append(row.get("check_in")).append(",");
105	            csv.append(row.get("check_out")).append("\n");
106	        }
107	        csv.append("total,").append(occupiedRooms.size()).append("/").append(allRooms.size()).append("\n");
108	
109	        return csv.toString();
110	    }
111	
112	    public static String generateRevenueReport(String monthStr) {
113	        YearMonth month;
114	        try {
115	            String[] parts = monthStr.split("-");
116	            if (parts.length != 2) {
117	                throw new IllegalArgumentException("Invalid month format. Expected yyyy-MM");
118	            }
119	            int year = Integer.parseInt(parts[0]);
120	            int monthNum = Integer.parseInt(parts[1]);
121	            month = YearMonth.of(year, monthNum);
122	        } catch (Exception e) {
123	            throw new IllegalArgumentException("Invalid month format. Expected yyyy-MM");
124	        }
125	
126	        List<Map<String, String>> revenues = new ArrayList<>();
127	        BigDecimal total = BigDecimal.ZERO;
128	
129	        try (Connection conn = Database.getConnection()) {
130	            String sql = """
131	                SELECT id, room_number, check_in, check_out, status, amount_paid, refund
132	                FROM reservations
133	                WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED')
134	                AND amount_paid > 0
135	                AND EXTRACT(YEAR FROM check_in) = ?
136	                AND EXTRACT(MONTH FROM check_in) = ?
137	                ORDER BY check_in, id
138	                """;
139	            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
140	                stmt.setInt(1, month.getYear());
141	                stmt.setInt(2, month.getMonthValue());
142	                try (ResultSet rs = stmt.executeQuery()) {
143	                    while (rs.next()) {
144	                        BigDecimal amountPaid = rs.getBigDecimal("amount_paid");
145	                        BigDecimal refund = rs.getBigDecimal("refund");
146	                        if (refund == null) refund = BigDecimal.ZERO;
147	
148	                        BigDecimal net = amountPaid.subtract(refund);
149	
150	                        Map<String, String> row = new HashMap<>();
151	                        row.put("reservation", String.valueOf(rs.getLong("id")));
152	                        row.put("room", String.valueOf(rs.getInt("room_number")));
153	                        row.put("check_in", DateParser.format(rs.getObject("check_in", LocalDate.class)));
154	                        row.put("check_out", DateParser.format(rs.getObject("check_out", LocalDate.class)));
155	                        row.put("status", rs.getString("status"));
156	                        row.put("amount", PriceFormatter.formatForCsv(net));
157	                        revenues.add(row);
158	
159	                        total = total.add(net);
160	                    }
161	                }
162	            }
163	        } catch (SQLException e) {
164	            throw new RuntimeException(e);
165	        }
166	
167	        StringBuilder csv = new StringBuilder();
168	        csv.append("reservation,room,check_in,check_out,status,amount\n");
169	        for (Map<String, String> row : revenues) {
170	            csv.append(row.get("reservation")).append(",");
171	            csv.append(row.get("room")).append(",");
172	            csv.append(row.get("check_in")).append(",");
173	            csv.append(row.get("check_out")).append(",");
174	            csv.append(row.get("status")).append(",");
175	            csv.append(row.get("amount")).append("\n");
176	        }
177	        csv.append("total,").append(PriceFormatter.formatForCsv(total)).append("\n");
178	
179	        return csv.toString();
180	    }
181	}
