     1	package com.pousadamarealta.utils;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	
     7	public class PriceCalculator {
     8	    private static final BigDecimal PEAK_SEASON_MULTIPLIER = new BigDecimal("1.20");
     9	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    10	
    11	    public static boolean isPeakSeason(LocalDate date) {
    12	        int month = date.getMonthValue();
    13	        int day = date.getDayOfMonth();
    14	
    15	        if (month == 7) return true;
    16	        if (month >= 12 && day >= 15) return true;
    17	        if (month <= 2) return true;
    18	        return false;
    19	    }
    20	
    21	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate night) {
    22	        if (isPeakSeason(night)) {
    23	            return baseRate.multiply(PEAK_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
    24	        }
    25	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
    26	    }
    27	
    28	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    29	        BigDecimal subtotal = BigDecimal.ZERO;
    30	        LocalDate current = checkIn;
    31	
    32	        while (current.isBefore(checkOut)) {
    33	            subtotal = subtotal.add(calculateNightlyRate(baseRate, current));
    34	            current = current.plusDays(1);
    35	        }
    36	
    37	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
    38	    }
    39	
    40	    public static BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
    41	        if (!isNonRefundable) {
    42	            return BigDecimal.ZERO;
    43	        }
    44	        return subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE).setScale(2, RoundingMode.HALF_EVEN);
    45	    }
    46	
    47	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    48	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
    49	    }
    50	
    51	    public static int countNights(LocalDate checkIn, LocalDate checkOut) {
    52	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    53	    }
    54	}
